alter table feedx_integrations.navigation_modules add constraint navigation_modules_coverage_check check(coverage in ('available','limited','unavailable'));
do $$declare d text;begin
 select pg_get_functiondef('feedx_integrations.navigation_catalog(uuid)'::regprocedure) into d;
 if position('''coverage'',n.coverage' in d)=0 then raise exception 'Coverage catalog drifted';end if;
 execute replace(d,'''coverage'',n.coverage','''coverage'',n.coverage,''capability_coverage'',n.coverage,''capability_limitation'',n.capability_limitation,''data_limitations'',n.explanation');
end $$;
